WITH with_windows AS (SELECT *, RANK() OVER w_running AS units_rank, ROUND(units / SUM(units) OVER (PARTITION BY product_id), 4) AS units_share, ROUND(revenue / SUM(revenue) OVER (PARTITION BY product_id), 4) AS revenue_share FROM store_sales WINDOW w_running AS (PARTITION BY store_id ORDER BY units DESC NULLS FIRST)), scored AS (SELECT *, COUNT(units_rank) OVER w_part AS sale_date_period_count_units_rank, AVG(revenue_share) OVER (ORDER BY units, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS revenue_share_avg_2_prior, LAST_VALUE(units_share, TRUE) OVER (PARTITION BY product_id ORDER BY sale_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_units_share, LAG(units_share, 2) OVER (PARTITION BY store_id ORDER BY units_share, id) AS prev_units_share, ROUND(revenue / SUM(revenue) OVER (PARTITION BY YEAR(sale_date)), 4) AS revenue_share_2 FROM with_windows WHERE units_rank <> 6 WINDOW w_part AS (PARTITION BY DATE_TRUNC('week', sale_date))), base AS (SELECT *, FLOOR(revenue_share_2) AS revenue_share_2_whole FROM scored WHERE sale_date >= DATE '2023-07-07'), joined AS (SELECT s.*, p.price FROM base s LEFT JOIN products p ON s.product_id = p.id), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id, product_id ORDER BY revenue_share_2 NULLS FIRST, id) AS row_num FROM joined QUALIFY row_num = 1) SELECT store_id, COUNT(*) AS num_rows, APPROX_PERCENTILE(units_share, ARRAY(0.25, 0.5, 0.75)) AS units_share_quartiles, SUM(units_share) AS total_units_share, BIT_OR(units) AS units_bit_or FROM ranked GROUP BY 1 ORDER BY store_id;
